import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for the node
  const root = new Group();

  // Plane geometry (unit size, will be scaled by the adapter if needed)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously and apply when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        /* texture failed to load – keep material untextured */
      });
  }

  // Apply cinematic primitives defined in config (none for this node)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive && primitive.name && ctx.primitives[primitive.name]) {
        const result = ctx.primitives[primitive.name](root, primitive.params || {});
        // Store cleanup for later
        (root.userData._primitiveCleanups = root.userData._primitiveCleanups || []).push(result);
      }
    }
  }

  // Event handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose of any primitive resources
    if (root.userData._primitiveCleanups) {
      for (const p of root.userData._primitiveCleanups) {
        if (p && typeof p.cleanup === 'function') p.cleanup();
        if (p && p.timeline) {
          p.timeline.kill();
        }
      }
      root.userData._primitiveCleanups = null;
    }

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();

    // Dispose Three.js resources
    material.dispose();
    geometry.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
  };

  return root;
}
